import unreal
TARGET='/Game/SSPR_Validation/NS_SSPR_ProjTest.NS_SSPR_ProjTest'
rows=[]
for comp in unreal.ObjectIterator(unreal.NiagaraComponent):
    try:
        asset=comp.get_editor_property('asset')
        if asset and asset.get_path_name()==TARGET:
            owner=comp.get_owner()
            rows.append({'component':comp.get_path_name(),'owner':owner.get_path_name() if owner else None,'active':bool(comp.is_active()),'autoActivate':bool(comp.get_editor_property('auto_activate')),'asset':asset.get_path_name()})
    except Exception as e:
        pass
print('MATCHING_COMPONENTS=' + repr(rows))
